{"attempt":{"agent":"real","id":"a_6227JJN79ZT72E524VWC9BAPR5","model":"@cf/zai-org/glm-5.3-flash","model_calls":8,"opened_seq":0,"repo":null,"steps":12,"tokens_in":41934,"tokens_out":839},"batch":{"id":1,"index":0,"size":1},"change_id":"c_000001","checks":[{"name":"replay","ok":true},{"name":"non_empty","ok":true},{"name":"fits","ok":true},{"name":"parse","ok":true},{"name":"imports_resolve","ok":true},{"name":"globals_allowed","ok":true},{"name":"derived","ok":true},{"detail":"11 premises at seq 0","name":"premises_hold","ok":true},{"detail":"auto","name":"policy","ok":true}],"confirms":[],"go_arounds":[],"hash_version":"ast1","intent":{"created_at":"2026-10-06T07:27:46.240Z","id":"i_7X2YB1HRSHGCXBKD62VPQRFGQ8","requester":"owner","text":"a sea urchin on the sand that waves its spines"},"judgments":[],"kind":"change","ops":[{"content":"// A sea urchin sitting on the sand, waving its spines slowly.
import { FLOOR_Y } from "../world/bounds.js";

const BODY = "purple";
const SPINE = "black";
const TUBE_FOOT = "pink";

const SPINES = 18;

// Wave phase in radians: the spines swing around the upright direction.
function sway(creature, i) {
  return Math.sin(creature.age * 0.05 + i * 1.7) * 0.25;
}

export function spawn(world) {
  return {
    x: Math.random() * world.bounds.POOL_WIDTH,
    y: FLOOR_Y - 8,
    vx: 0,
    vy: 0,
  };
}

export function update(creature) {
  creature.vx = 0;
  creature.vy = 0;
}

export function draw(creature, pen) {
  // Body
  pen.fill(BODY);
  pen.stroke(SPINE, 2);
  pen.circle(0, 0, 14);

  // Spines radiating out, each swaying a little.
  pen.stroke(SPINE, 2);
  for (let i = 0; i < SPINES; i++) {
    const a = (i / SPINES) * Math.PI * 2 + sway(creature, i);
    const cos = Math.cos(a);
    const sin = Math.sin(a);
    pen.line(14 * cos, 14 * sin, 30 * cos, 30 * sin);
  }

  // A few pink tube feet between the spines.
  pen.stroke(TUBE_FOOT, 2);
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * Math.PI * 2 + sway(creature, i + 3) * 1.6;
    const cos = Math.cos(a);
    const sin = Math.sin(a);
    pen.line(10 * cos, 10 * sin, 22 * cos, 22 * sin);
  }
}
