// True when the creature is below HUNGRY_BELOW.
export function isHungry(creature) {
  return creature.energy < HUNGRY_BELOW;
}

// The pellet closest to the creature, or null when there is none.
export function nearestFood(creature, world) {
  let best = null;
  let bestFar = Infinity;
  for (const pellet of world.food) {
    const far = Math.hypot(pellet.x - creature.x, pellet.y - creature.y);
    if (far < bestFar) {
      best = pellet;
      bestFar = far;
    }
  }
  return best;
}

// Move the creature by its speed (vx, vy), never faster than MAX_SPEED.
export function step(creature) {
  const speed = Math.hypot(creature.vx, creature.vy);
  if (speed > MAX_SPEED) {
    creature.vx = (creature.vx / speed) * MAX_SPEED;
    creature.vy = (creature.vy / speed) * MAX_SPEED;
  }
  creature.x += creature.vx;
  creature.y += creature.vy;
}

// Push the creature toward the point (x, y). `push` is the speed added this tick.
export function steer(creature, x, y, push) {
  const dx = x - creature.x;
  const dy = y - creature.y;
  const far = Math.hypot(dx, dy);
  if (far < 0.001) return;
  creature.vx += (dx / far) * push;
  creature.vy += (dy / far) * push;
}

// Slow down. `keep` is the share of speed kept this tick, for example 0.95.
export function glide(creature, keep) {
  creature.vx *= keep;
  creature.vy *= keep;
}

// Turn around at the edges of the water.
export function bounce(creature) {
  if (creature.x < 0 || creature.x > POOL_WIDTH) creature.vx = -creature.vx;
  if (creature.y < SURFACE_Y || creature.y > FLOOR_Y) creature.vy = -creature.vy;
  keepInside(creature);
}

// True from sunset to sunrise.
export function isNight(world) {
  return dayPhase(world) >= 0.5;
}

