nd":"entity","new":"040770d8beb38d6eae885e19f75437c4","old":"040770d8beb38d6eae885e19f75437c4","reason":"blind_spot","result":"confirm","rule":"B1"}],"kind":"change","ops":[{"content":"import { ENERGY_MAX } from "../world/energy.js";
