  pen.ellipse(18, 0, 9, 6);
  pen.fill("black");
  pen.circle(21, -3, 1.5);

  // antennae
  pen.stroke(LEG, 1);
  pen.line(24, -4, 32, -10);
  pen.line(24, -2, 34, -4);

  // claws
  pen.fill(CLAW);
  pen.ellipse(24, 8, 7, 4);
  pen.poly([27, 6, 35, 4, 28, 11]);
}
