// Take energy away. `amount` is in the same unit as ENERGY_MAX.
export function drain(creature, amount) {
  creature.energy = Math.max(0, creature.energy - amount);
}

// Move the creature by its speed (vx, vy), never faster than MAX_SPEED.
export function step(creature) {
  const speed = Math.hypot(creature.vx, creature.vy);
  if (speed > MAX_SPEED) {
    creature.vx = (creature.vx / speed) * MAX_SPEED;
    creature.vy = (creature.vy / speed) * MAX_SPEED;
  }
  creature.x += creature.vx;
  creature.y += creature.vy;
}

// Slow down. `keep` is the share of speed kept this tick, for example 0.95.
export function glide(creature, keep) {
  creature.vx *= keep;
  creature.vy *= keep;
}

// Leave through one side wall and come back in through the other.
export function wrap(creature) {
  if (creature.x < 0) creature.x += POOL_WIDTH;
  if (creature.x > POOL_WIDTH) creature.x -= POOL_WIDTH;
  creature.y = Math.min(FLOOR_Y, Math.max(SURFACE_Y, creature.y));
}

