esult":"confirm","rule":"B1"}],"kind":"change","ops":[{"content":"import { ENERGY_MAX, drain } from "../world/energy.js";
import { wander, glide, step } from "../world/movement.js";
import { wrap } from "../world/bounds.js";
import { seconds } from "../world/time.js";

const BODY = "pink";
const TAIL = "coral";
const EYE = "black";

const DART_EVERY = seconds(2); // ticks between darts
const DART_COST = (5 / 100) * ENERGY_MAX; // energy spent on each dart
const DART_PUSH = 3;

export function spawn() {
  return { nextDart: DART_EVERY, energy: ENERGY_MAX };
}

export function update(shrimp, world) {
  shrimp.nextDart -= 1;
  if (shrimp.nextDart <= 0) {
    wander(shrimp, DART_PUSH);
    drain(shrimp, DART_COST);
    shrimp.nextDart = DART_EVERY;
  }
  glide(shrimp, 0.9);
  step(shrimp);
  wrap(shrimp);
}

export function draw(shrimp, pen) {
  if (shrimp.vx < 0) pen.flip();
  pen.fill(TAIL);
  pen.poly([-12, 0, -22, -9, -22, 9]);
  pen.fill(BODY);
  pen.ellipse(0, 0, 16, 7);
  pen.fill(BODY);
  pen.ellipse(10, 2, 6, 4);
  pen.fill(EYE);
  pen.circle(10, 1, 1.5);
}
